using Xunit;

public class TokenBucketTests
{
    [Fact]
    public void StartsFullAndDrains()
    {
        var b = new TokenBucket(3, 1);
        Assert.True(b.Allow(0));
        Assert.True(b.Allow(0));
        Assert.True(b.Allow(0));
        Assert.False(b.Allow(0));
    }

    [Fact]
    public void RefillsOverTime()
    {
        var b = new TokenBucket(3, 1);
        for (int i = 0; i < 3; i++) b.Allow(0);
        Assert.False(b.Allow(0.5));
        Assert.True(b.Allow(1.0));
        Assert.False(b.Allow(1.0));
    }

    [Fact]
    public void RefillCapsAtCapacity()
    {
        var b = new TokenBucket(2, 1);
        b.Allow(0);
        b.Allow(0);
        Assert.True(b.Allow(1000));
        Assert.True(b.Allow(1000));
        Assert.False(b.Allow(1000));
    }
}
